import{_ as r,I as t,c as n,o as s,a3 as a,b as o,w as e,a as h,J as d,a4 as p}from"./chunks/framework.BusRvirq.js";const y=JSON.parse('{"title":"재해 복구(DR) 및 고가용성 설계","description":"엔터프라이즈 환경에서 데이터 무결성을 보장하고 RTO 15분 이내 시스템 복구를 달성하기 위한 고가용성(HA) 및 재해 복구(DR) 가이드","frontmatter":{"title":"재해 복구(DR) 및 고가용성 설계","shortTitle":"재해 복구 & DR","category":"인프라 & 보안","sort":5,"description":"엔터프라이즈 환경에서 데이터 무결성을 보장하고 RTO 15분 이내 시스템 복구를 달성하기 위한 고가용성(HA) 및 재해 복구(DR) 가이드","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/infra/disaster-recovery.html"}]]},"headers":[],"relativePath":"infra/disaster-recovery.md","filePath":"ko/infra/disaster-recovery.md","lastUpdated":1791239682000}'),B={name:"infra/disaster-recovery.md"};function c(E,i,k,g,A,_){const l=t("Mermaid");return s(),n("div",null,[i[1]||(i[1]=a('<h1 id="재해-복구-dr-및-고가용성-설계" tabindex="-1">재해 복구(DR) 및 고가용성 설계 <a class="header-anchor" href="#재해-복구-dr-및-고가용성-설계" aria-label="Permalink to “재해 복구(DR) 및 고가용성 설계”">​</a></h1><h2 id="_1-개요-및-복구-목표-기준" tabindex="-1">1. 개요 및 복구 목표 기준 <a class="header-anchor" href="#_1-개요-및-복구-목표-기준" aria-label="Permalink to “1. 개요 및 복구 목표 기준”">​</a></h2><p>SyncSeries는 데이터 손실이 치명적인 금융, 제조, 공공 서비스를 안정적으로 지원하기 위해 명확한 복구 목표 지표(RPO, RTO)를 정의하고 다중 리전 및 이중화 인프라를 운영합니다.</p><ul><li><strong>RPO (Recovery Point Objective - 목표 복구 시점)</strong>: <strong>0분</strong> (동기식 복제 환경 기준) / 최대 1분 이내 (비동기 교차 리전 복제 기준).</li><li><strong>RTO (Recovery Time Objective - 목표 복구 시간)</strong>: <strong>15분 이내</strong> (주 센터 장애 시 보조 센터로의 트래픽 전환 완료 기준).</li></ul>',4)),(s(),o(p,null,{default:e(()=>[d(l,{id:"mermaid-21",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20PrimaryDC%20%5B%22%EC%A3%BC%20%EB%8D%B0%EC%9D%B4%ED%84%B0%EC%84%BC%ED%84%B0%20(Active)%22%5D%0A%20%20%20%20%20%20%20%20K8s_P%5B%22%EC%BF%A0%EB%B2%84%EB%84%A4%ED%8B%B0%EC%8A%A4%20%EC%9B%8C%EC%BB%A4%20%EB%85%B8%EB%93%9C%22%5D%0A%20%20%20%20%20%20%20%20PG_P%5B(%22PostgreSQL%2017%20Primary%22)%5D%0A%20%20%20%20%20%20%20%20Redis_P%5B(%22Redis%20Primary%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SecondaryDC%20%5B%22%EC%9E%AC%ED%95%B4%EB%B3%B5%EA%B5%AC%20%EC%84%BC%ED%84%B0%20(Standby)%22%5D%0A%20%20%20%20%20%20%20%20K8s_S%5B%22%EC%BF%A0%EB%B2%84%EB%84%A4%ED%8B%B0%EC%8A%A4%20%EB%8C%80%EA%B8%B0%20%EB%85%B8%EB%93%9C%22%5D%0A%20%20%20%20%20%20%20%20PG_S%5B(%22PostgreSQL%2017%20Standby%22)%5D%0A%20%20%20%20%20%20%20%20Redis_S%5B(%22Redis%20Replica%22)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20GSLB%5B%22GSLB%20%2F%20DNS%20%ED%8A%B8%EB%9E%98%ED%94%BD%20%EB%9D%BC%EC%9A%B0%ED%84%B0%22%5D%20--%3E%20PrimaryDC%0A%20%20%20%20GSLB%20-.-%3E%20%7C%EC%9E%A5%EC%95%A0%20%EC%8B%9C%2015%EB%B6%84%20%EB%82%B4%20%EC%A0%84%ED%99%98%7C%20SecondaryDC%0A%20%20%20%20%0A%20%20%20%20PG_P%20--%3E%20%7C%EB%8F%99%EA%B8%B0%EC%8B%9D%20WAL%20%EC%8A%A4%ED%8A%B8%EB%A6%AC%EB%B0%8D%20%EB%B3%B5%EC%A0%9C%7C%20PG_S%0A%20%20%20%20Redis_P%20--%3E%20%7C%EB%B9%84%EB%8F%99%EA%B8%B0%20%EB%A9%94%EB%AA%A8%EB%A6%AC%20%EB%B3%B5%EC%A0%9C%7C%20Redis_S%0A"})]),fallback:e(()=>[...i[0]||(i[0]=[h(" Loading... ",-1)])]),_:1})),i[2]||(i[2]=a(`<hr><h2 id="_2-데이터-계층-고가용성-및-복제-아키텍처" tabindex="-1">2. 데이터 계층 고가용성 및 복제 아키텍처 <a class="header-anchor" href="#_2-데이터-계층-고가용성-및-복제-아키텍처" aria-label="Permalink to “2. 데이터 계층 고가용성 및 복제 아키텍처”">​</a></h2><h3 id="_1-postgresql-17-pgvector-wal-스트리밍-복제" tabindex="-1">1) PostgreSQL 17 (pgvector) WAL 스트리밍 복제 <a class="header-anchor" href="#_1-postgresql-17-pgvector-wal-스트리밍-복제" aria-label="Permalink to “1) PostgreSQL 17 (pgvector) WAL 스트리밍 복제”">​</a></h3><ul><li>비즈니스 테이블 및 AI 임베딩 벡터 데이터의 일관성을 유지하기 위해 PostgreSQL 17의 물리 스트리밍 복제(Physical Streaming Replication)를 적용합니다.</li><li><code>synchronous_commit = on</code> 설정을 통해 트랜잭션 커밋 신호가 보조 노드의 WAL(Write-Ahead Log)에 기록된 후 최종 클라이언트 응답을 반환하여 장애 시 커밋 유실을 방지합니다.</li></ul><div class="language-ini"><button title="Copy code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># postgresql.conf (Primary)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">wal_level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = replica</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max_wal_senders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 10</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">wal_keep_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 4096MB</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">synchronous_commit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = on</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">synchronous_standby_names</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;FIRST 1 (dr_standby_node)&#39;</span></span></code></pre></div><h3 id="_2-시점-복구-pitr-point-in-time-recovery-파이프라인" tabindex="-1">2) 시점 복구(PITR: Point-In-Time Recovery) 파이프라인 <a class="header-anchor" href="#_2-시점-복구-pitr-point-in-time-recovery-파이프라인" aria-label="Permalink to “2) 시점 복구(PITR: Point-In-Time Recovery) 파이프라인”">​</a></h3><ul><li>매일 02:00에 기본 전체 백업(Base Backup)을 MinIO 오브젝트 스토리지에 압축 암호화 적재합니다.</li><li>지속적으로 생성되는 WAL 아카이브 파일은 60초 주기로 보조 스토리지로 동기화되어, 관리자 실수로 인한 데이터 오염 발생 시 특정 분/초 단위로 데이터베이스를 정밀하게 복원할 수 있는 PITR 환경을 제공합니다.</li></ul><hr><h2 id="_3-redis-분산-락-및-세션-복제" tabindex="-1">3. Redis 분산 락 및 세션 복제 <a class="header-anchor" href="#_3-redis-분산-락-및-세션-복제" aria-label="Permalink to “3. Redis 분산 락 및 세션 복제”">​</a></h2><ul><li>에이전트 간 동시 작업 충돌을 방지하는 분산 락(Redlock)과 활성 사용자 세션은 Redis Sentinel 기반의 3노드 자동 페일오버 클러스터로 구성됩니다.</li><li>마스터 노드에 심각한 하드웨어 장애가 발생할 경우 Sentinel 정족수(Quorum) 합의를 통해 3초 이내에 보조 노드가 새로운 마스터로 자동 승격됩니다.</li></ul><hr><h2 id="_4-재해-발생-시-단계별-페일오버-절차" tabindex="-1">4. 재해 발생 시 단계별 페일오버 절차 <a class="header-anchor" href="#_4-재해-발생-시-단계별-페일오버-절차" aria-label="Permalink to “4. 재해 발생 시 단계별 페일오버 절차”">​</a></h2><p>주 데이터센터의 물리적 침수, 전력 단전 또는 통신망 단절 사고 발생 시 아래의 표준 운영 절차(SOP)에 따라 대기 센터로 전환합니다.</p><ol><li><strong>상태 감지 및 장애 선언 (0 ~ 3분)</strong>: <ul><li>외부 헬스체크 프로브 3곳에서 주 센터의 5xx 에러 또는 응답 무응답이 180초 이상 지속될 경우 인프라 위기 경보를 발령합니다.</li></ul></li><li><strong>보조 데이터베이스 승격 (3 ~ 7분)</strong>: <ul><li>재해복구 센터의 PostgreSQL Standby 노드에서 승격 명령을 실행하여 읽기/쓰기 모드로 전환합니다:<div class="language-bash"><button title="Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pg_ctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> promote</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/lib/postgresql/data</span></span></code></pre></div></li></ul></li><li><strong>쿠버네티스 파드 스케일아웃 및 기동 (7 ~ 10분)</strong>: <ul><li>보조 클러스터의 도메인 에이전트 Deployment 복제본 수를 평시 대기 상태(1대)에서 운영 사양(최소 3대 이상)으로 즉시 스케일아웃합니다.</li></ul></li><li><strong>GSLB 트래픽 전환 (10 ~ 15분)</strong>: <ul><li>글로벌 서버 로드 밸런서(GSLB)의 가중치를 주 센터 0%, 보조 센터 100%로 전환하고 DNS TTL(60초) 만료를 기다립니다.</li><li>서비스 정상 유입 및 인가 토큰 세션의 정상 검증 여부를 최종 확인합니다.</li></ul></li></ol><hr><h2 id="_5-정기-모의-훈련-및-복구-검증" tabindex="-1">5. 정기 모의 훈련 및 복구 검증 <a class="header-anchor" href="#_5-정기-모의-훈련-및-복구-검증" aria-label="Permalink to “5. 정기 모의 훈련 및 복구 검증”">​</a></h2><ul><li><strong>훈련 주기</strong>: 분기 1회 정기 DR 모의 훈련을 실시합니다.</li><li><strong>검증 항목</strong>: <ul><li>실제 주 센터 네트워크 인터페이스 강제 차단 후 트래픽 전환 완료 시간 측정.</li><li>전환 완료 후 에이전트 작업 히스토리 및 RAG 벡터 색인의 데이터 누락(0건) 전수 대조.</li><li>모의 훈련 결과 리포트를 작성하여 엔터프라이즈 컴플라이언스 감사 증적으로 보관.</li></ul></li></ul>`,17))])}const D=r(B,[["render",c]]);export{y as __pageData,D as default};
